              "tier1": [
                "show ipv6 interface GigabitEthernet0/0/0/1",
                "show ipv6 neighbors",
                "show dhcpv6 server binding"
              ],
              "tier2": [
                "show ipv6 traffic",
                "show logging | include DHCPv6",
                "show dhcpv6 relay statistics"
              ],
              "tier3": [
                "debug ipv6 nd",
                "debug dhcpv6 server",
                "debug dhcpv6 relay"
              ]
